static int posix_arch_console_init(void)
{
#ifdef CONFIG_PRINTK
	__printk_hook_install(print_char);
#endif
#ifdef CONFIG_STDOUT_CONSOLE
	__stdout_hook_install(print_char);
#endif
	return 0;
}
